def build():
    out = {"// edit i18n_source.py, not this file": ["", "", ""]}
    out.update({k: list(v) for k, v in T.items()})
    path = Path(__file__).with_name("static") / "i18n.json"
    path.write_text(json.dumps(out, ensure_ascii=False, indent=0) + "\n", encoding="utf-8")
    return path, len(T)


if __name__ == "__main__":
    p, n = build()
    print(f"{n} texts -> {p}")
